   "body": [
    {
     "t": "code",
     "lang": "python",
     "code": "class Node:\n    def __init__(self, value):\n        self.value = value\n        self.next = None\n\ndef has_cycle(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow = slow.next            # one step\n        fast = fast.next.next       # two steps\n        if slow is fast:            # they can only meet inside a loop\n            return True\n    return False\n\na, b, c = Node(1), Node(2), Node(3)\na.next, b.next = b, c\nprint(has_cycle(a))         # Output: False\nc.next = a                  # close the loop\nprint(has_cycle(a))         # Output: True\n\n# Floyd's tortoise and hare: O(n) time, O(1) memory - no set of seen nodes.",
     "numbered": false
    }
   ]
